# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
import type {AIProvider, MessageChunk, SendMessageParams, StructuredOutputParams} from '../../types/ai.js';

export interface MockConfig {
  type: 'mock';
  structuredResponses?: Map<string, unknown>;
}

export function createMockProvider(config?: MockConfig): AIProvider {
  const structuredResponses = config?.structuredResponses ?? new Map<string, unknown>();

  return {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : 'Hello';

      const response = `Mock response to: "${userText}"`;

      for (const word of response.split(' ')) {
        yield {type: 'text', text: word + ' '};
      }

      yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 10, outputTokens: 20, totalTokens: 30}};
    },

    async generateStructured<T>(params: StructuredOutputParams<T>): Promise<T> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : '';

      const preconfigured = structuredResponses.get(userText);
      if (preconfigured !== undefined) return preconfigured as T;

      return buildDefaultResponse(params.responseSchema) as T;
    },
  };
}

// Factories, not values: `array` must hand back a fresh [] to each caller.
const SCALAR_DEFAULTS: Record<string, () => unknown> = {
  array: () => [],
  string: () => '',
  number: () => 0,
  boolean: () => false,
};

function buildDefaultResponse(schema: {type: string; properties?: Record<string, {type: string}>}): unknown {
  if (schema.type === 'object') {
    const result: Record<string, unknown> = {};
    for (const [key, prop] of Object.entries(schema.properties ?? {})) {
      result[key] = buildDefaultResponse(prop);
    }
    return result;
  }

  const scalar = SCALAR_DEFAULTS[schema.type];
  return scalar ? scalar() : null;
}
import type {AIProvider, MessageChunk, SendMessageParams, StructuredOutputParams} from '../types/ai.js';
import {AIError} from '../types/ai.js';
import {log} from '../shared/logger.js';

export interface RetryPolicy {
  maxAttempts?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
  firstChunkTimeoutMs?: number;
  idleChunkTimeoutMs?: number;
}

const DEFAULTS: Required<RetryPolicy> = {
  maxAttempts: 3,
  baseDelayMs: 500,
  maxDelayMs: 5000,
  firstChunkTimeoutMs: 30000,
  idleChunkTimeoutMs: 30000,
};

export function withRetry(provider: AIProvider, policy: RetryPolicy = {}): AIProvider {
  const p: Required<RetryPolicy> = {...DEFAULTS, ...policy};

  return {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      let lastError: AIError | undefined;

      for (let attempt = 1; attempt <= p.maxAttempts; attempt++) {
        if (attempt > 1) await applyBackoff(attempt, lastError, p);

        const iter = provider.sendMessage(params);
        let firstChunkHandedOff = false;

        try {
          const firstTimeout = makeTimeout(p.firstChunkTimeoutMs);
          let firstResult: IteratorResult<MessageChunk>;
          try {
            firstResult = await Promise.race([iter.next(), firstTimeout.promise]);
            firstTimeout.cancel();
          } catch (err) {
            firstTimeout.cancel();
            void iter.return(undefined);
            if (!(err instanceof AIError)) throw err;
            if (err.code === 'TIMEOUT') {
              // eslint-disable-next-line re-lint/no-flag-params -- AIError's retryable flag; see adrs/ADR-006-lint-suppressions.md
              lastError = new AIError('first chunk timeout', 'TIMEOUT', true);
              continue;
            }
            if (!err.retryable) throw err;
            lastError = err;
            continue;
          }

          if (firstResult.done) return;

          firstChunkHandedOff = true;
          yield firstResult.value;
          yield* streamWithIdleTimeout(iter, p.idleChunkTimeoutMs);
          return;
        } catch (err) {
          if (firstChunkHandedOff) throw err;
          if (!(err instanceof AIError) || !err.retryable) throw err;
          lastError = err;
        }
      }

      throw lastError ?? new AIError('max attempts exhausted', 'RETRY_EXHAUSTED');
    },

    async generateStructured<T>(params: StructuredOutputParams<T>): Promise<T> {
      let lastError: AIError | undefined;

      for (let attempt = 1; attempt <= p.maxAttempts; attempt++) {
        if (attempt > 1) await applyBackoff(attempt, lastError, p);
        try {
          return await provider.generateStructured(params);
        } catch (err) {
          if (!(err instanceof AIError) || !err.retryable) throw err;
          lastError = err;
        }
      }

      throw lastError ?? new AIError('max attempts exhausted', 'RETRY_EXHAUSTED');
    },
  };
}

async function applyBackoff(attempt: number, lastError: AIError | undefined, p: Required<RetryPolicy>): Promise<void> {
  const wait = jitterDelay(attempt - 1, p);
  log.warn('withRetry', 'retrying provider call', {attempt, code: lastError?.code, delay: wait});
  await sleep(wait);
}

async function* streamWithIdleTimeout(
  iter: AsyncGenerator<MessageChunk>,
  idleChunkTimeoutMs: number
): AsyncGenerator<MessageChunk> {
  while (true) {
    const idleTimeout = makeTimeout(idleChunkTimeoutMs);
    let nextResult: IteratorResult<MessageChunk>;
    try {
      nextResult = await Promise.race([iter.next(), idleTimeout.promise]);
      idleTimeout.cancel();
    } catch (err) {
      idleTimeout.cancel();
      void iter.return(undefined);
      throw err;
    }
    if (nextResult.done) return;
    yield nextResult.value;
  }
}

function makeTimeout(ms: number): {promise: Promise<never>; cancel: () => void} {
  let cancel: () => void = () => {};
  const promise = new Promise<never>((_, reject) => {
    // eslint-disable-next-line re-lint/no-flag-params -- AIError's retryable flag; see adrs/ADR-006-lint-suppressions.md
    const id = setTimeout(() => reject(new AIError('chunk timeout', 'TIMEOUT', false)), ms);
    cancel = () => clearTimeout(id);
  });
  return {promise, cancel};
}

function jitterDelay(retryIndex: number, p: Required<RetryPolicy>): number {
  const cap = Math.min(p.maxDelayMs, p.baseDelayMs * Math.pow(2, retryIndex - 1));
  return Math.floor(Math.random() * (cap + 1));
}

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}
